static J *checks;static int failures;
void d408_check(const char *suite,int passed,const char *name){J *check=cJSON_CreateObject();ss(check,"suite",suite);ss(check,"name",name);set(check,"passed",cJSON_CreateBool(passed));cJSON_AddItemToArray(checks,check);printf("D408 %s [%s] %s\n",passed?"PASS":"FAIL",suite,name);if(!passed)failures++;}
static void pump(void){MSG m;int n=0;while(n++<300&&PeekMessageW(&m,0,0,0,PM_REMOVE)){if(!d408_translate_message(&m)&&!detail_translate_message(&m)){TranslateMessage(&m);DispatchMessageW(&m);}}}
static int press(HWND input,int control,int shift){BYTE old[256],keys[256];GetKeyboardState(old);memcpy(keys,old,256);keys[VK_CONTROL]=control?0x80:0;keys[VK_SHIFT]=shift?0x80:0;SetKeyboardState(keys);SetFocus(input);MSG m={0};m.hwnd=input;m.message=WM_KEYDOWN;m.wParam=VK_RETURN;m.lParam=1|((LPARAM)MapVirtualKeyW(VK_RETURN,MAPVK_VK_TO_VSC)<<16);int handled=d408_input_message(&m);if(!handled)detail_translate_message(&m);pump();SetKeyboardState(old);return handled;}
static J *task_state(void){return app.editor?db_row(&app.db,app.editor->key):0;}
static int text_is(HWND h,const char *value){char *text=ui_text(h);int equal=!strcmp(text,value);free(text);return equal;}
