 ui_set(d->fields[8],"D408 saved notes");press(d->fields[8],1,0);row=task_state();d408_check("keyboard",!strcmp(str(get(row,"data"),"notes"),"D408 saved notes"),"Ctrl Enter from notes persists task");cJSON_Delete(row);
